                Variables.Record(Name + "_Allegiance", I.SystemAllegiance);
                Variables.Record(Name + "_Government", I.SystemGovernment_Localised);
                Variables.Record(Name + "_PrimaryEconomy", I.SystemEconomy_Localised);
